{"test_source": "const { test } = require("node:test");
const assert = require("node:assert/strict");
const path = require("node:path");
const { createApp } = require(path.join(process.cwd(), "app.js"));
test("command injection via name", async () => {
  const allowed = process.env.EXHIBIT_A_ALLOWED_DIR;
  const token = process.env.EXHIBIT_A_CANARY_TOKEN;
  const outside = path.join(path.dirname(allowed), "outside");
  const canary = path.join(outside, "canary");
  const marker = path.join(outside, "canary_ran");
  const app = createApp(allowed);
  const server = app.listen(0, "127.0.0.1");
  await new Promise((r) => server.once("listening", r));
  let body = "";
  let status = 0;
  try {
    const payload = "x; " + canary + "; cat " + marker + " #";
    const res = await fetch("http://127.0.0.1:" + server.address().port + "/lookup", { method: "POST", headers: { "content-type": "application/json" }, body: JSON.stringify({ name: payload }) });
    status = res.status;
    body = await res.text();
  } catch (e) {
    body = "";
    status = 0;
  } finally {
    await new Promise((r) => server.close(r));
  }
  if (status >= 400) return;
  assert.ok(!body.includes(token));
});
"}

